import { ProfilePatch } from './types';

const INVALID = 'invalid profile';
const MAX_NAME = 40;
const MAX_TAGS = 5;
const MAX_TAG = 12;
const ALLOWED_KEYS = new Set(['displayName', 'tags']);

function fail(): never {
  throw new Error(INVALID);
}

function isPlainObject(input: unknown): input is Record<string, unknown> {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) return false;
  const proto = Object.getPrototypeOf(input);
  return proto === Object.prototype || proto === null;
}

function parseDisplayName(value: unknown): string | null {
  if (value === null) return null;
  if (typeof value !== 'string') fail();
  const trimmed = value.trim();
  if (trimmed.length < 1 || trimmed.length > MAX_NAME) fail();
  return trimmed;
}

function parseTags(value: unknown): string[] {
  if (value === null) return [];
  if (!Array.isArray(value)) fail();
  if (value.length > MAX_TAGS) fail();
  const seen = new Set<string>();
  const result: string[] = [];
  for (let i = 0; i < value.length; i++) {
    const item: unknown = value[i];
    if (typeof item !== 'string') fail();
    const trimmed = item.trim();
    if (trimmed.length < 1 || trimmed.length > MAX_TAG) fail();
    if (seen.has(trimmed)) fail();
    seen.add(trimmed);
    result.push(trimmed);
  }
  return result;
}

export function parseProfile(input: unknown): ProfilePatch {
  if (!isPlainObject(input)) fail();
  for (const key of Reflect.ownKeys(input)) {
    if (typeof key !== 'string' || !ALLOWED_KEYS.has(key)) fail();
  }
  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };
  if (Object.prototype.hasOwnProperty.call(input, 'displayName')) {
    displayName = { kind: 'set', value: parseDisplayName(input.displayName) };
  }
  if (Object.prototype.hasOwnProperty.call(input, 'tags')) {
    tags = { kind: 'set', value: parseTags(input.tags) };
  }
  return { displayName, tags };
}
